print('st61 complete staged',len(roots),'roots',len(W),'newwords',sum(len(x['examples']) for x in W),'examples','cumulative',len(progress['completed_roots']),len(progress['completed_words']))
requests=[]
for name,pos,en,note in [('says','verb','The third-person singular present form of say.','Oxford say 动词变化表核 /sez/；现代语法为 say + -s，不能沿用原形双元音。'),('gainsay','verb','To deny or contradict a statement or fact.','IPA 和中古英语构词核 Oxford；MW 明确 gain- 来自古英语反对，与现代 gain 获得另源。'),('naysayer','noun','A person who habitually rejects ideas or says that something cannot be done.','Oxford 核 IPA；MW 及 Wiktionary 核 nay/say/-er 材料与现代否定倾向义。')]:
 x=next(x for x in W if x['word']==name)
 requests.append(dict(word=name,pos=pos,ipa=x['ipa'],definition_zh=x['meaning'],definition_en=en,etymology_text=x['split'],sources=x['sources'],note=note))
Path('.cache/batch200/st61-supplement-request.json').write_text(json.dumps(requests,ensure_ascii=False,indent=2)+'\n')
